class HomeScreen extends ConsumerWidget {
  const HomeScreen({super.key});

  void _handleMemberAction(BuildContext context, String route, bool hasMember) {
    if (!hasMember) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please choose a family member first to access this feature.',
          ),
          duration: Duration(seconds: 3),
        ),
      );
      context.push('/members');
    } else {
      context.push(route);
    }
  }

  String _getInitials(String? name) {
    if (name == null || name.trim().isEmpty) return 'FV';
    final parts =
        name.trim().split(RegExp(r'\s+')).where((p) => p.isNotEmpty).toList();
    if (parts.isEmpty) return 'FV';
    if (parts.length == 1) return parts[0].characters.first.toUpperCase();
    return (parts[0].characters.first + parts[1].characters.first)
        .toUpperCase();
  }

