  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final activeId = ref.watch(activeMemberProvider);
    final membersAsync = ref.watch(membersProvider);
    final members = membersAsync.valueOrNull ?? const [];
    final activeMember = members
        .where((member) => member.id == activeId)
        .firstOrNull;
    final activeName = activeMember?.displayName;
    final activeRole = activeMember?.relationshipLabel;
    final theme = Theme.of(context);
    final hasMember = activeId != null;

    // Auto-select first member if none is currently selected
    ref.listen<AsyncValue<List<Member>>>(membersProvider, (_, next) {
      final items = next.valueOrNull;
      if (items != null &&
          items.isNotEmpty &&
          ref.read(activeMemberProvider) == null) {
        final firstId = items.first.id;
        ref.read(activeMemberProvider.notifier).state = firstId;
        final userId = ref.read(authProvider).userId;
        if (userId != null) {
          ref.read(memberPreferenceStoreProvider).writeActiveMemberId(
            userId: userId,
            memberId: firstId,
          );
        }
      }
    });

    if (activeId == null && members.isNotEmpty) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (ref.read(activeMemberProvider) == null) {
          final firstId = members.first.id;
          ref.read(activeMemberProvider.notifier).state = firstId;
          final userId = ref.read(authProvider).userId;
          if (userId != null) {
            ref.read(memberPreferenceStoreProvider).writeActiveMemberId(
              userId: userId,
              memberId: firstId,
            );
          }
        }
      });
    }

    return Scaffold(
      backgroundColor: Colors.transparent,
      // The only live blur on this screen. Budget: 1 of FvGlass.blurBudget.
      appBar: GlassAppBar(
        title: const Text('Family Veda'),
        actions: [
          IconButton(
            tooltip: 'Profile details',
            onPressed: () => _showProfileBottomSheet(
              context,
              ref,
              activeMember,
              ref.read(authProvider).userId,
            ),
            icon: CircleAvatar(
              radius: 14,
              backgroundColor: Theme.of(context)
                  .colorScheme
                  .primary
                  .withValues(alpha: 0.2),
              child: Text(
                _getInitials(activeName),
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                  color: Theme.of(context).colorScheme.primary,
                ),
              ),
            ),
          ),
          IconButton(
            tooltip: 'Toggle theme',
            onPressed: () {
              final current = ref.read(themeModeProvider);
              final isDark = current == ThemeMode.dark;
              ref.read(themeModeProvider.notifier).state =
                  isDark ? ThemeMode.light : ThemeMode.dark;
            },
            icon: Icon(
              Theme.of(context).brightness == Brightness.dark
                  ? Icons.light_mode_outlined
                  : Icons.dark_mode_outlined,
            ),
          ),
          IconButton(
            tooltip: 'Notifications',
            onPressed: () => context.push('/notifications'),
            icon: const Icon(Icons.notifications_outlined),
          ),
          IconButton(
            tooltip: 'Sign out',
            onPressed: () async {
              final signedOut = await logoutAndClearMember(ref);
              if (!signedOut && context.mounted) {
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(
                    content: Text(
                      'Sign out could not be completed. Check your connection and try again.',
                    ),
                  ),
                );
              }
            },
            icon: const Icon(Icons.logout),
          ),
        ],
      ),
      body: SafeArea(
        top: false,
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
          children: [
            // Active Patient Profile Card
            GlassCard(
              onTap: () => _showProfileBottomSheet(
                context,
                ref,
                activeMember,
                ref.read(authProvider).userId,
              ),
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
              child: Row(
                children: [
                  // Profile Avatar with Initials & Active indicator
                  Stack(
                    children: [
                      Container(
