                                  style: TextStyle(
                                    fontSize: 11,
                                    fontWeight: FontWeight.w600,
                                    color: Theme.of(context).colorScheme.primary,
                                  ),
                                ),
                              ),
                            ],
                          ],
                        ),
                        const SizedBox(height: 3),
                        Row(
                          children: [
                            Icon(
                              Icons.verified_user_outlined,
                              size: 13,
                              color: context.glass.faint,
                            ),
                            const SizedBox(width: 4),
                            Expanded(
                              child: Text(
                                hasMember
